package com.spendwise.transaction;import org.springframework.http.HttpStatus;import org.springframework.stereotype.Service;import org.springframework.transaction.annotation.Transactional;import org.springframework.web.server.ResponseStatusException;import java.time.LocalDate;import java.util.List;
@Service public class TransactionService{private final TransactionRepository repository;public TransactionService(TransactionRepository r){repository=r;}
public List<Transaction> list(String month,String email){if(month==null||month.isBlank())return repository.findAllByUserEmailOrderByDateDesc(email);try{LocalDate s=LocalDate.parse(month+"-01");return repository.findAllByUserEmailAndDateBetweenOrderByDateDesc(email,s,s.withDayOfMonth(s.lengthOfMonth()));}catch(RuntimeException e){throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Month must use yyyy-MM format");}}
@Transactional public Transaction create(TransactionRequest r,String email){Transaction t=new Transaction();apply(t,r);t.setUserEmail(email);return repository.save(t);}
@Transactional public Transaction update(Long id,TransactionRequest r,String email){Transaction t=owned(id,email);apply(t,r);return repository.save(t);}
@Transactional public void delete(Long id,String email){repository.delete(owned(id,email));}
private Transaction owned(Long id,String email){return repository.findByIdAndUserEmail(id,email).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Transaction not found"));}
private void apply(Transaction t,TransactionRequest r){t.setTitle(r.title().trim());t.setAmount(r.amount());t.setType(r.type());t.setCategory(r.category().trim());t.setDate(r.date());t.setPaymentMethod(r.paymentMethod().trim());t.setNotes(r.notes()==null||r.notes().isBlank()?null:r.notes().trim());}}